/* ═══════════════════════════════════════════════════════════════
   Island Vibrancy — Custom UI CSS
   Rounded, modern PHPStorm Island-inspired layout for VS Code
   ═══════════════════════════════════════════════════════════════ */

/* ─── Root variables ─────────────────────────────────────────── */
:root {
  --iv-radius:        10px;
  --iv-radius-sm:     6px;
  --iv-radius-lg:     14px;
  --iv-gap:           6px;
  --iv-shadow:        0 4px 20px rgba(0, 0, 0, 0.25);
  --iv-shadow-sm:     0 2px 8px rgba(0, 0, 0, 0.15);
}

/* ─── Editor area — breathing room around editor ─────────────── */
.editor-group-container {
  border-radius: var(--iv-radius) !important;
  overflow: hidden !important;
}

.split-view-view:first-child .editor-group-container {
  margin-left: 4px !important;
}

/* ─── Tabs — rounded pill-style ──────────────────────────────── */
.tabs-container {
  padding: 6px 6px 0 !important;
  gap: 2px !important;
}

.tab {
  border-radius: var(--iv-radius-sm) var(--iv-radius-sm) 0 0 !important;
  margin-right: 2px !important;
  border: none !important;
  padding: 0 14px !important;
  transition: background 0.15s ease !important;
}

.tab.active {
  border-radius: var(--iv-radius-sm) var(--iv-radius-sm) 0 0 !important;
  border-bottom: none !important;
}

/* Tabs scroll left/right buttons */
.tabs-and-actions-container .action-item .action-label {
  border-radius: var(--iv-radius-sm) !important;
}

/* ─── Activity bar — pill-style icons ────────────────────────── */
.activitybar {
  border-right: none !important;
  padding: 8px 4px !important;
}

.activitybar .action-item {
  border-radius: var(--iv-radius-sm) !important;
  margin: 2px 4px !important;
  width: calc(100% - 8px) !important;
}

.activitybar .action-item.checked,
.activitybar .action-item:hover {
  border-radius: var(--iv-radius-sm) !important;
}

.activitybar .active-item-indicator {
  border-radius: 2px !important;
  width: 3px !important;
  left: 0 !important;
}

/* ─── Sidebar — rounded panels ───────────────────────────────── */
.sidebar {
  border-right: none !important;
}

.pane-header {
  border-radius: var(--iv-radius-sm) var(--iv-radius-sm) 0 0 !important;
  padding: 6px 12px !important;
  letter-spacing: 0.04em !important;
  font-size: 11px !important;
  text-transform: uppercase !important;
}

.pane-body {
  padding: 4px !important;
}

/* ─── File Explorer tree items ───────────────────────────────── */
.monaco-list-row {
  border-radius: var(--iv-radius-sm) !important;
  margin: 1px 4px !important;
  width: calc(100% - 8px) !important;
}

.monaco-list-row.focused,
.monaco-list-row.selected {
  border-radius: var(--iv-radius-sm) !important;
}

/* ─── Bottom panel ───────────────────────────────────────────── */
.panel {
  border-top: none !important;
}

.panel .title {
  border-radius: 0 !important;
  padding: 0 12px !important;
}

.panel .panel-switcher-container .action-item {
  border-radius: var(--iv-radius-sm) var(--iv-radius-sm) 0 0 !important;
  margin-right: 2px !important;
  padding: 0 10px !important;
}

/* ─── Status bar ─────────────────────────────────────────────── */
.statusbar {
  border-top: none !important;
}

.statusbar-item {
  border-radius: var(--iv-radius-sm) !important;
  margin: 3px 1px !important;
  padding: 0 8px !important;
}

/* ─── Scrollbars — thin & modern ─────────────────────────────── */
::-webkit-scrollbar {
  width: 6px !important;
  height: 6px !important;
}

::-webkit-scrollbar-track {
  background: transparent !important;
  border-radius: 3px !important;
}

::-webkit-scrollbar-thumb {
  border-radius: 3px !important;
  min-height: 40px !important;
}

::-webkit-scrollbar-corner {
  background: transparent !important;
}

/* ─── Autocomplete / Suggest widget ─────────────────────────── */
.suggest-widget {
  border-radius: var(--iv-radius) !important;
  overflow: hidden !important;
  box-shadow: var(--iv-shadow) !important;
  border: 1px solid rgba(126, 200, 227, 0.15) !important;
}

.suggest-widget .monaco-list-row {
  border-radius: var(--iv-radius-sm) !important;
  margin: 1px 4px !important;
  width: calc(100% - 8px) !important;
}

.suggest-widget .details {
  border-left: 1px solid rgba(126, 200, 227, 0.1) !important;
  border-radius: 0 var(--iv-radius) var(--iv-radius) 0 !important;
}

/* ─── Hover widget ───────────────────────────────────────────── */
.monaco-editor .overlayWidgets .hover-widget,
.monaco-editor-hover {
  border-radius: var(--iv-radius) !important;
  box-shadow: var(--iv-shadow) !important;
  overflow: hidden !important;
  border: 1px solid rgba(126, 200, 227, 0.15) !important;
}

/* ─── Quick input / Command palette ──────────────────────────── */
.quick-input-widget {
  border-radius: var(--iv-radius-lg) !important;
  overflow: hidden !important;
  box-shadow: var(--iv-shadow) !important;
  border: 1px solid rgba(126, 200, 227, 0.15) !important;
  top: 10% !important;
}

.quick-input-box .input {
  border-radius: var(--iv-radius-sm) !important;
  padding: 8px 14px !important;
  font-size: 13px !important;
}

.quick-input-list .monaco-list-row {
  border-radius: var(--iv-radius-sm) !important;
  margin: 1px 6px !important;
  width: calc(100% - 12px) !important;
}

.quick-input-list-entry {
  padding: 4px 8px !important;
}

/* ─── Notifications ──────────────────────────────────────────── */
.notifications-toasts .notification-toast {
  border-radius: var(--iv-radius) !important;
  box-shadow: var(--iv-shadow) !important;
  overflow: hidden !important;
  margin-bottom: 8px !important;
}

/* ─── Context menu / dropdown ────────────────────────────────── */
.context-view .monaco-menu {
  border-radius: var(--iv-radius) !important;
  overflow: hidden !important;
  box-shadow: var(--iv-shadow) !important;
  padding: 4px !important;
}

.monaco-menu .action-item {
  border-radius: var(--iv-radius-sm) !important;
}

.monaco-menu .separator {
  margin: 3px 8px !important;
}

/* ─── Input fields ───────────────────────────────────────────── */
.monaco-inputbox {
  border-radius: var(--iv-radius-sm) !important;
  overflow: hidden !important;
}

.monaco-inputbox .wrapper,
.monaco-inputbox input {
  border-radius: var(--iv-radius-sm) !important;
}

/* ─── Buttons ────────────────────────────────────────────────── */
.monaco-button {
  border-radius: var(--iv-radius-sm) !important;
  padding: 5px 14px !important;
  font-weight: 500 !important;
}

/* ─── Breadcrumbs ────────────────────────────────────────────── */
.monaco-breadcrumbs {
  padding: 4px 12px !important;
}

.monaco-breadcrumb-item {
  border-radius: 4px !important;
  padding: 2px 6px !important;
}

/* ─── Minimap — rounded edges ────────────────────────────────── */
.minimap {
  border-radius: 0 var(--iv-radius-sm) 0 0 !important;
  overflow: hidden !important;
}

/* ─── Panel drag handles — subtle ────────────────────────────── */
.sash {
  border-radius: 2px !important;
  opacity: 0 !important;
  transition: opacity 0.2s ease !important;
}

.sash:hover,
.sash.active {
  opacity: 1 !important;
}

/* ─── Peek view ──────────────────────────────────────────────── */
.peekview-widget {
  border-radius: var(--iv-radius) !important;
  overflow: hidden !important;
  box-shadow: var(--iv-shadow) !important;
}

/* ─── Diff editor ────────────────────────────────────────────── */
.monaco-diff-editor .gutter {
  border-radius: 0 !important;
}

/* ─── Editor group drop zone ─────────────────────────────────── */
.editor-group-drop-overlay {
  border-radius: var(--iv-radius) !important;
}

/* ─── Loading bar / progress ─────────────────────────────────── */
.monaco-progress-container .progress-bit {
  border-radius: 2px !important;
}

/* ─── Inlay hints ────────────────────────────────────────────── */
.monaco-editor .inlayHints-widget {
  border-radius: 4px !important;
  padding: 1px 5px !important;
}

/* ─── Find widget ────────────────────────────────────────────── */
.editor-widget.find-widget {
  border-radius: var(--iv-radius) !important;
  overflow: hidden !important;
  box-shadow: var(--iv-shadow) !important;
}

/* ─── Rename widget ──────────────────────────────────────────── */
.monaco-editor .rename-box {
  border-radius: var(--iv-radius-sm) !important;
}

/* ─── Banner (top info bar) ──────────────────────────────────── */
.editor-banner {
  border-radius: 0 0 var(--iv-radius-sm) var(--iv-radius-sm) !important;
}

