{
    "gitlens.ai.model": "vscode",
    "gitlens.ai.vscode.model": "copilot:gpt-4.1",
    "launch": {
        "configurations": [],
        "compounds": []
    },
    "chat.tools.terminal.autoApprove": {
        "./bin/setup-tests-local.sh": true,
        "./vendor/bin/phpunit": true,
        "./bin/install-wp-tests.sh": true,
        "./.vscode/bin/dev-watcher.sh": true,
        "sed": true,
        "git fetch": true,
        "git checkout": true,
        "/^php -l rocket-lazy-load\\.php$/": {
            "approve": true,
            "matchCommandLine": true
        },
        "/^npm run build:css 2>&1 \\| grep -E \"\\(Finished\\|Error\\)\"$/": {
            "approve": true,
            "matchCommandLine": true
        },
        "/^php -d memory_limit=512M vendor/bin/phpunit --configuration tests/Unit/phpunit\\.xml\\.dist --testdox tests/Unit/inc/Engine/Admin/RocketInsights/APIHandler/APIClient/addToQueue\\.php tests/Unit/inc/Engine/Admin/RocketInsights/Jobs/Manager/attemptSyncSubmission\\.php$/": {
            "approve": true,
            "matchCommandLine": true
        },
        "gulp": true,
        "npx": true,
        "post.*list\"": true,

