1	/* Islands Dark custom workbench CSS.
2	 * Load with Custom CSS and JS Loader: be5invis.vscode-custom-css
3	 */
4	
5	.monaco-workbench {
6		--islands-panel-radius: 24px;
7		--islands-widget-radius: 14px;
8		--islands-input-radius: 12px;
9		--islands-item-radius: 6px;
10		--islands-panel-gap: 6px;
11		--islands-panel-top: 6px;
12		--islands-bg-canvas: #121216;
13		--islands-bg-surface: #181a1d;
14		background-color: var(--islands-bg-canvas) !important;
15	}
16	
17	.part.sidebar {
18		font-family: 'Bear Sans UI', sans-serif !important;
19		margin: var(--islands-panel-top) var(--islands-panel-gap) 0 var(--islands-panel-gap);
20		border-radius: var(--islands-panel-radius) !important;
21		overflow: hidden !important;
22		max-height: calc(100% - 8px) !important;
23		border-top: 1px solid rgba(255,255,255,0.1) !important;
24		border-left: 1px solid rgba(255,255,255,0.06) !important;
25		border-bottom: 1px solid rgba(255,255,255,0.02) !important;
26		border-right: 1px solid rgba(255,255,255,0.02) !important;
27		box-shadow: 0 2px 8px 0 rgba(0,0,0,0.3) !important;
28	}
29	
30	.part.sidebar .composite.title {
31		padding: 8px 20px 0 0 !important;
32	}
33	
34	.part.sidebar .title-label h2 {
35		font-family: 'Bear Sans UI Heading', sans-serif !important;
36		font-size: 12px !important;
37		font-weight: 700 !important;
38		text-transform: uppercase !important;
39		letter-spacing: 1px !important;
40	}
41	
42	.part.sidebar .content {
43		width: calc(100% - 20px) !important;
44		padding-left: 10px !important;
45		margin-left: 6px !important;
46	}
47	
48	.part.sidebar .welcome-view-content {
49		max-width: 100% !important;
50		box-sizing: border-box !important;
51	}
52	
53	.part.sidebar .pane-header {
54		border-radius: var(--islands-item-radius) !important;
55		outline-offset: -1px !important;
56	}
57	
58	.explorer-viewlet .split-view-container {
59		margin-top: -22px !important;
60	}
61	
62	.part.sidebar .header {
63		padding-right: 20px !important;
64	}
65	
66	.part.sidebar .label-name {
67		font-size: 13px !important;
