655		background-color: var(--islands-bg-surface) !important;
656		border-radius: var(--islands-widget-radius) !important;
657		border-top: 1px solid rgba(255,255,255,0.1) !important;
658		border-left: 1px solid rgba(255,255,255,0.06) !important;
659		border-bottom: 1px solid rgba(255,255,255,0.02) !important;
660		border-right: 1px solid rgba(255,255,255,0.02) !important;
661		overflow: hidden !important;
662	}
663	
664	.chat-input-container .monaco-inputbox {
665		background-color: var(--islands-bg-surface) !important;
666	}
667	
668	.interactive-input-part {
669		border-radius: var(--islands-widget-radius) !important;
670		overflow: hidden !important;
671	}
672	
673	.monaco-button-dropdown-separator {
674		display: none !important;
675		background: transparent !important;
676		background-color: transparent !important;
677		width: 0 !important;
678		opacity: 0 !important;
679	}
680	
681	/* Islands Dark — Living Glass
682	   Ambient aurora light, liquid motion, breathing panels */
683	
684	/* ===== Animatable Custom Properties ===== */
685	@property --border-angle {
686	  syntax: '<angle>';
687	  initial-value: 0deg;
688	  inherits: false;
689	}
690	
691	/* ===== Keyframes ===== */
692	
693	/* Aurora: colored light traveling along panel borders */
694	@keyframes islands-aurora {
695	  to { --border-angle: 360deg; }
696	}
697	
698	/* Activity bar: liquid drop funnels into the new divot */
699	@keyframes islands-drop-morph {
700	  0% {
701	    transform: scaleX(0.45) scaleY(2);
702	    opacity: 0;
703	    border-radius: 35%;
704	  }
705	  20% {
706	    opacity: 0.7;
707	    border-radius: 40%;
708	    transform: scaleX(0.5) scaleY(1.5);
709	  }
710	  50% {
711	    transform: scaleX(1.2) scaleY(0.8);
712	    opacity: 1;
713	    border-radius: 50%;
714	  }
715	  70% { transform: scaleX(0.92) scaleY(1.08); }
716	  85% { transform: scaleX(1.04) scaleY(0.96); }
717	  100% {
718	    transform: scaleX(1) scaleY(1);
719	    opacity: 1;
720	    border-radius: 50%;
721	  }
722	}
723	
724	/* Soft breathing glow on active indicator */
725	@keyframes islands-breathe {
726	  0%, 100% { filter: drop-shadow(0 0 2px rgba(13,188,121,0)); }
727	  50% { filter: drop-shadow(0 0 8px rgba(13,188,121,0.3)); }
728	}
729	
730	/* Widget entrance — lift into place */
731	@keyframes islands-emerge {
732	  from {
733	    opacity: 0;
734	    transform: translateY(-4px) scale(0.98);
735	  }
736	  to {
737	    opacity: 1;
738	    transform: translateY(0) scale(1);
739	  }
740	}
741	
742	/* Notification entrance — slide + scale from right */
743	@keyframes islands-notify {
744	  from {
745	    opacity: 0;
746	    transform: translateX(20px) scale(0.96);
747	  }
748	  to {
749	    opacity: 1;
750	    transform: translateX(0) scale(1);
751	  }
752	}
753	
754	
755	/* =============================================================
756	   AURORA BORDERS — Living Glass
757	   A subtle colored light continuously travels along panel edges,
758	   making the glass borders feel alive.
759	   ============================================================= */
760	
761	.part.sidebar::after,
762	.part.editor::after,
763	.part.auxiliarybar::after,
764	.part.panel.bottom::after {
765	  content: '' !important;
766	  display: block !important;
767	  position: absolute !important;
768	  inset: 0 !important;
769	  border-radius: inherit !important;
770	  padding: 1px !important;
771	  background: conic-gradient(
772	    from var(--border-angle),
773	    transparent 0%,
774	    transparent 20%,
775	    rgba(13,188,121,0.35) 27%,
776	    rgba(125,200,160,0.2) 33%,
777	    rgba(13,188,121,0.12) 38%,
778	    transparent 45%,
779	    transparent 100%
780	  ) !important;
781	  -webkit-mask:
782	    linear-gradient(#fff 0 0) content-box,
783	    linear-gradient(#fff 0 0) !important;
784	  -webkit-mask-composite: xor !important;
785	  pointer-events: none !important;
786	  z-index: 999 !important;
787	  animation: islands-aurora 8s linear infinite !important;
788	}
789	
790	/* Stagger panels so the light is out of phase */
791	.part.editor::after {
792	  animation-delay: -2s !important;
793	}
794	.part.auxiliarybar::after {
795	  animation-delay: -4s !important;
796	}
797	.part.panel.bottom::after {
798	  animation-delay: -6s !important;
799	}
800	
801	
802	/* =============================================================
803	   ACTIVITY BAR — Liquid Motion
804	   ============================================================= */
805	
806	/* Drop morph when switching, then settle into a breathing glow */
807	.part.activitybar .action-item.checked .action-label {
808	  animation:
809	    islands-drop-morph 0.4s cubic-bezier(0.22, 1, 0.36, 1),
810	    islands-breathe 4s ease-in-out 0.5s infinite !important;
811	}
812	
813	/* Hover glow on all activity bar icons */
814	.part.activitybar .action-item .action-label {
815	  transition: filter 0.3s ease !important;
816	}
817	.part.activitybar .action-item:hover .action-label {
818	  filter: drop-shadow(0 0 5px rgba(13,188,121,0.25)) !important;
819	}
820	
821	
822	/* =============================================================
823	   WIDGET ENTRANCES
824	   ============================================================= */
825	
826	/* Command palette — lifts into view */
827	.quick-input-widget {
828	  animation: islands-emerge 0.2s cubic-bezier(0.16, 1, 0.3, 1) !important;
829	}
830	
831	/* Notifications — slide from right with scale */
832	.notification-toast {
833	  animation: islands-notify 0.35s cubic-bezier(0.16, 1, 0.3, 1) !important;
834	}
835	
836	/* Dialog boxes */
837	.monaco-dialog-box {
838	  animation: islands-emerge 0.25s cubic-bezier(0.16, 1, 0.3, 1) !important;
839	}
840	
841	/* Hover tooltips */
842	.monaco-hover {
843	  animation: islands-emerge 0.15s ease-out !important;
844	}
845	
846	/* Autocomplete */
847	.editor-widget.suggest-widget {
848	  animation: islands-emerge 0.12s cubic-bezier(0.16, 1, 0.3, 1) !important;
849	}
850	
851	/* Notification center */
852	.notifications-center {
853	  animation: islands-emerge 0.2s cubic-bezier(0.16, 1, 0.3, 1) !important;
854	}
855	
856	/* Copilot chat fixes */
857	.chat-list-container {
858	  overflow-y: auto !important;
859	}
860	
861	.chat-attached-context {
862	  overflow: visible !important;
863	  max-height: none !important;
864	}
865	
866	.context-attachments {
867	  overflow: visible !important;
868	}
869	
870	.interactive-input-part {
871	  overflow: visible !important;
872	}
