/* ═══════════════════════════════════════════════════════════════
   Island Vibrancy — Color Addon
   Overrides palette variables from islands-dark.css to apply
   the Island Vibrancy tropical color scheme.
   ═══════════════════════════════════════════════════════════════ */

.monaco-workbench {
  --islands-bg-canvas:  #111522;
  --islands-bg-surface: #1B1F2E;
}

/* ─── Aurora border — teal/cyan tropical palette ─────────────── */
.part.sidebar::after,
.part.editor::after,
.part.auxiliarybar::after,
.part.panel.bottom::after {
  background: conic-gradient(
    from var(--border-angle),
    transparent 0%,
    transparent 20%,
    rgba(126, 200, 227, 0.35) 27%,
    rgba(165, 236, 255, 0.2)  33%,
    rgba(120, 219, 169, 0.15) 38%,
    transparent 45%,
    transparent 100%
  ) !important;
}

/* ─── Activity bar — tropical glow on hover & active ─────────── */
.part.activitybar .action-item.checked .action-label {
  background: linear-gradient(180deg, rgba(42, 50, 80, 0.9), rgba(30, 35, 56, 0.75)) !important;
  box-shadow:
    inset 0 1px 0 0 rgba(126, 200, 227, 0.18),
    inset 1px 0 0 0 rgba(126, 200, 227, 0.10),
    inset 0 -1px 0 0 rgba(126, 200, 227, 0.04),
    inset -1px 0 0 0 rgba(126, 200, 227, 0.04),
    0 1px 3px 0 rgba(0, 0, 0, 0.35) !important;
}

.part.activitybar .action-item:hover .action-label {
  filter: drop-shadow(0 0 5px rgba(126, 200, 227, 0.30)) !important;
}

/* ─── Activity bar composite bar — teal accent breathing ─────── */
@keyframes islands-breathe {
  0%, 100% { filter: drop-shadow(0 0 2px rgba(126, 200, 227, 0)); }
  50%       { filter: drop-shadow(0 0 8px rgba(126, 200, 227, 0.28)); }
}

/* ─── Sidebar panel border glass ─────────────────────────────── */
.part.sidebar,
.part.editor,
.part.auxiliarybar,
.part.panel.bottom {
  border-top:    1px solid rgba(126, 200, 227, 0.12) !important;
  border-left:   1px solid rgba(126, 200, 227, 0.07) !important;
  border-bottom: 1px solid rgba(126, 200, 227, 0.03) !important;
  border-right:  1px solid rgba(126, 200, 227, 0.03) !important;
}

/* ─── Editor tabs bottom separator line ──────────────────────── */
.editor-actions {
  background-image: linear-gradient(to top, #1E2338 1px, transparent 1px) !important;
}
.tabs-container {
  background-image: linear-gradient(to top, #1E2338 1px, transparent 1px) !important;
}
.tab.active {
  box-shadow: inset -1px 0 0 0 #1E2338, inset 1px 0 0 0 #1E2338 !important;
}
.tab:not(.active) {
  box-shadow: inset 0 -1px 0 0 #1E2338 !important;
}

/* ─── Command center bar ──────────────────────────────────────── */
.command-center-center {
  background: color-mix(in srgb, #111522, #1B1F2E 30%) !important;
  box-shadow:
    inset 0 1px 0 0 rgba(126, 200, 227, 0.12),
    inset 1px 0 0 0 rgba(126, 200, 227, 0.07),
    inset 0 -1px 0 0 rgba(126, 200, 227, 0.03),
    inset -1px 0 0 0 rgba(126, 200, 227, 0.03),
    0 1px 4px 0 rgba(0, 0, 0, 0.28) !important;
}

/* ─── Activity bar pill ───────────────────────────────────────── */
.part.activitybar .composite-bar {
  background: color-mix(in srgb, #111522, #1B1F2E 30%) !important;
  border-top:    1px solid rgba(126, 200, 227, 0.14) !important;
  border-left:   1px solid rgba(126, 200, 227, 0.08) !important;
  border-bottom: 1px solid rgba(126, 200, 227, 0.03) !important;
  border-right:  1px solid rgba(126, 200, 227, 0.05) !important;
}

/* ─── Quick input / palette glass ────────────────────────────── */
.quick-input-widget {
  border-top:    1px solid rgba(126, 200, 227, 0.14) !important;
  border-left:   1px solid rgba(126, 200, 227, 0.08) !important;
  border-bottom: 1px solid rgba(126, 200, 227, 0.03) !important;
  border-right:  1px solid rgba(126, 200, 227, 0.03) !important;
}

/* ─── Notification toasts ─────────────────────────────────────── */
.notification-toast,
.notifications-center {
  border-top:    1px solid rgba(126, 200, 227, 0.12) !important;
  border-left:   1px solid rgba(126, 200, 227, 0.07) !important;
  border-bottom: 1px solid rgba(126, 200, 227, 0.03) !important;
  border-right:  1px solid rgba(126, 200, 227, 0.03) !important;
}

/* ─── Dialog box glass ───────────────────────────────────────── */
.monaco-dialog-box {
  border-top:    1px solid rgba(126, 200, 227, 0.12) !important;
  border-left:   1px solid rgba(126, 200, 227, 0.07) !important;
  border-bottom: 1px solid rgba(126, 200, 227, 0.03) !important;
  border-right:  1px solid rgba(126, 200, 227, 0.03) !important;
}

/* ─── Selected list items — teal tint ────────────────────────── */
.part.sidebar .monaco-list-row.focused,
.quick-input-widget .monaco-list-row.focused {
  background: linear-gradient(135deg, rgba(42, 51, 80, 0.7), rgba(30, 38, 60, 0.5)) !important;
  box-shadow: inset 0 0 0 1px rgba(126, 200, 227, 0.09) !important;
}

.part.sidebar .monaco-list-row.focused.selected,
.part.sidebar .monaco-list:focus .monaco-list-row.focused {
  background: linear-gradient(135deg, rgba(42, 51, 80, 0.85), rgba(30, 38, 60, 0.65)) !important;
  box-shadow: inset 0 0 0 1px rgba(126, 200, 227, 0.12) !important;
}

/* ─── Chat input ─────────────────────────────────────────────── */
.chat-input-container {
  background-color: #1B1F2E !important;
  border-top:    1px solid rgba(126, 200, 227, 0.12) !important;
  border-left:   1px solid rgba(126, 200, 227, 0.07) !important;
  border-bottom: 1px solid rgba(126, 200, 227, 0.03) !important;
  border-right:  1px solid rgba(126, 200, 227, 0.03) !important;
}
.chat-input-container .monaco-inputbox {
  background-color: #1B1F2E !important;
}

