/* ═══════════════════════════════════════════════════════════════
   LIGHT MODE OVERRIDES  (.vscode-light is added by VS Code when
   a light theme is active — all rules here are light-only)
   ═══════════════════════════════════════════════════════════════ */

/* ─── Canvas / surface palette ───────────────────────────────── */
.vscode-light .monaco-workbench {
  --islands-bg-canvas:  #EDE8E0;
  --islands-bg-surface: #F5F1EB;
}

/* ─── Main workbench background ──────────────────────────────── */
.vscode-light .monaco-workbench {
  background-color: var(--islands-bg-canvas) !important;
}

/* ─── Floating panels — warm sand glass ──────────────────────── */
.vscode-light .part.sidebar,
.vscode-light .part.editor,
.vscode-light .part.auxiliarybar,
.vscode-light .part.panel.bottom {
  border-top:    1px solid rgba(46, 134, 171, 0.18) !important;
  border-left:   1px solid rgba(46, 134, 171, 0.10) !important;
  border-bottom: 1px solid rgba(46, 134, 171, 0.05) !important;
  border-right:  1px solid rgba(46, 134, 171, 0.05) !important;
  box-shadow: 0 2px 8px 0 rgba(0, 0, 0, 0.10) !important;
}

/* ─── Aurora border — warm ocean tints for light mode ────────── */
.vscode-light .part.sidebar::after,
.vscode-light .part.editor::after,
.vscode-light .part.auxiliarybar::after,
.vscode-light .part.panel.bottom::after {
  background: conic-gradient(
    from var(--border-angle),
    transparent 0%,
    transparent 20%,
    rgba(46, 134, 171, 0.45)  27%,
    rgba(26, 143, 160, 0.25)  33%,
    rgba(46, 158, 104, 0.18)  38%,
    transparent 45%,
    transparent 100%
  ) !important;
}

/* ─── Activity bar pill ───────────────────────────────────────── */
.vscode-light .part.activitybar {
  background: var(--islands-bg-canvas) !important;
}

.vscode-light .part.activitybar .composite-bar {
  background: color-mix(in srgb, #EDE8E0, #F5F1EB 30%) !important;
  border-top:    1px solid rgba(46, 134, 171, 0.20) !important;
  border-left:   1px solid rgba(46, 134, 171, 0.12) !important;
  border-bottom: 1px solid rgba(0, 0, 0, 0.04) !important;
  border-right:  1px solid rgba(0, 0, 0, 0.04) !important;
  box-shadow: inset 0 1px 3px 0 rgba(255,255,255,0.7), 0 1px 4px 0 rgba(0,0,0,0.08) !important;
}

/* ─── Activity bar active/hover icons ────────────────────────── */
.vscode-light .part.activitybar .action-item.checked .action-label {
  background: linear-gradient(180deg, rgba(210, 225, 240, 0.9), rgba(195, 215, 232, 0.75)) !important;
  box-shadow:
    inset 0 1px 0 0 rgba(255, 255, 255, 0.8),
    inset 1px 0 0 0 rgba(255, 255, 255, 0.5),
    inset 0 -1px 0 0 rgba(46, 134, 171, 0.08),
    0 1px 3px 0 rgba(0, 0, 0, 0.12) !important;
}

.vscode-light .part.activitybar .action-item:hover .action-label {
  filter: drop-shadow(0 0 5px rgba(46, 134, 171, 0.35)) !important;
}

/* ─── Breathing glow — ocean blue for light ──────────────────── */
@keyframes islands-breathe-light {
  0%, 100% { filter: drop-shadow(0 0 2px rgba(46, 134, 171, 0)); }
  50%       { filter: drop-shadow(0 0 8px rgba(46, 134, 171, 0.30)); }
}
.vscode-light .part.activitybar .action-item.checked .action-label {
  animation:
    islands-drop-morph 0.4s cubic-bezier(0.22, 1, 0.36, 1),
    islands-breathe-light 4s ease-in-out 0.5s infinite !important;
}

/* ─── Title & status bars ─────────────────────────────────────── */
.vscode-light .part.titlebar {
  background-color: var(--islands-bg-canvas) !important;
}

.vscode-light .part.statusbar {
  background-color: var(--islands-bg-canvas) !important;
}

.vscode-light .part.statusbar:hover .statusbar-item-label,
.vscode-light .part.statusbar:hover .codicon {
  color: #6B6055 !important;
}

/* ─── Tab separator lines ─────────────────────────────────────── */
.vscode-light .editor-actions {
  background-image: linear-gradient(to top, #D4CEC4 1px, transparent 1px) !important;
}
.vscode-light .tabs-container {
  background-image: linear-gradient(to top, #D4CEC4 1px, transparent 1px) !important;
}
.vscode-light .tab.active {
  box-shadow: inset -1px 0 0 0 #D4CEC4, inset 1px 0 0 0 #D4CEC4 !important;
}
.vscode-light .tab:not(.active) {
  box-shadow: inset 0 -1px 0 0 #D4CEC4 !important;
}

/* ─── Command center ─────────────────────────────────────────── */
.vscode-light .command-center-center {
  background: color-mix(in srgb, #EDE8E0, #F5F1EB 30%) !important;
  box-shadow:
    inset 0 1px 0 0 rgba(255, 255, 255, 0.7),
    inset 1px 0 0 0 rgba(255, 255, 255, 0.4),
    inset 0 -1px 0 0 rgba(0, 0, 0, 0.05),
    inset -1px 0 0 0 rgba(0, 0, 0, 0.05),
    0 1px 4px 0 rgba(0, 0, 0, 0.12) !important;
}

/* ─── Bottom panel background ────────────────────────────────── */
.vscode-light .part.panel.bottom {
  background-color: var(--islands-bg-surface) !important;
  border-top: 6px solid var(--islands-bg-canvas) !important;
  border-left: 6px solid var(--islands-bg-canvas) !important;
  border-right: 6px solid var(--islands-bg-canvas) !important;
}

/* ─── Sidebar list items ─────────────────────────────────────── */
.vscode-light .part.sidebar .monaco-list-row:hover {
  background: linear-gradient(135deg, rgba(190, 210, 230, 0.35), rgba(175, 200, 220, 0.20)) !important;
}

.vscode-light .part.sidebar .monaco-list-row.focused,
.vscode-light .quick-input-widget .monaco-list-row.focused {
  background: linear-gradient(135deg, rgba(180, 205, 230, 0.65), rgba(165, 195, 220, 0.45)) !important;
  box-shadow: inset 0 0 0 1px rgba(46, 134, 171, 0.12) !important;
}

.vscode-light .part.sidebar .monaco-list-row.focused.selected,
.vscode-light .part.sidebar .monaco-list:focus .monaco-list-row.focused {
  background: linear-gradient(135deg, rgba(180, 205, 230, 0.80), rgba(165, 195, 220, 0.60)) !important;
  box-shadow: inset 0 0 0 1px rgba(46, 134, 171, 0.16) !important;
}

/* ─── Quick input / palette ──────────────────────────────────── */
.vscode-light .quick-input-widget {
  border-top:    1px solid rgba(46, 134, 171, 0.18) !important;
  border-left:   1px solid rgba(46, 134, 171, 0.10) !important;
  border-bottom: 1px solid rgba(0, 0, 0, 0.05) !important;
  border-right:  1px solid rgba(0, 0, 0, 0.05) !important;
  box-shadow: 0 8px 24px 0 rgba(0, 0, 0, 0.18) !important;
}

/* ─── Notifications / dialogs ────────────────────────────────── */
.vscode-light .notification-toast,
.vscode-light .notifications-center,
.vscode-light .monaco-dialog-box {
  border-top:    1px solid rgba(255, 255, 255, 0.8) !important;
  border-left:   1px solid rgba(255, 255, 255, 0.5) !important;
  border-bottom: 1px solid rgba(0, 0, 0, 0.06) !important;
  border-right:  1px solid rgba(0, 0, 0, 0.04) !important;
  box-shadow: 0 4px 12px 0 rgba(0, 0, 0, 0.15) !important;
}

/* ─── Hover widget ───────────────────────────────────────────── */
.vscode-light .monaco-hover {
  border: 1px solid rgba(0, 0, 0, 0.10) !important;
  box-shadow: 0 4px 16px 0 rgba(0, 0, 0, 0.15) !important;
}

/* ─── File icons — subtle glow ───────────────────────────────── */
.vscode-light .monaco-icon-label.file-icon::before {
  filter: drop-shadow(0 0 2px currentColor);
  opacity: 0.85 !important;
}

/* ─── Chat input ─────────────────────────────────────────────── */
.vscode-light .chat-input-container {
  background-color: #F5F1EB !important;
  border-top:    1px solid rgba(46, 134, 171, 0.16) !important;
  border-left:   1px solid rgba(46, 134, 171, 0.09) !important;
  border-bottom: 1px solid rgba(0, 0, 0, 0.04) !important;
  border-right:  1px solid rgba(0, 0, 0, 0.04) !important;
}
.vscode-light .chat-input-container .monaco-inputbox {
  background-color: #F5F1EB !important;
}

