/* ═══════════════════════════════════════════════════════════════
   Island Vibrancy — Color Addon
   Overrides palette variables from islands-dark.css to apply
   the Island Vibrancy tropical color scheme.
   ═══════════════════════════════════════════════════════════════ */

.monaco-workbench {
  --islands-bg-canvas:  #111522;
  --islands-bg-surface: #1B1F2E;
}

/* ─── Aurora border — teal/cyan tropical palette ─────────────── */
.part.sidebar::after,
.part.editor::after,
.part.auxiliarybar::after,
.part.panel.bottom::after {
  background: conic-gradient(
    from var(--border-angle),
    transparent 0%,
    transparent 20%,
    rgba(126, 200, 227, 0.35) 27%,
    rgba(165, 236, 255, 0.2)  33%,
    rgba(120, 219, 169, 0.15) 38%,
    transparent 45%,
    transparent 100%
  ) !important;
}

/* ─── Activity bar — tropical glow on hover & active ─────────── */
.part.activitybar .action-item.checked .action-label {
  background: linear-gradient(180deg, rgba(42, 50, 80, 0.9), rgba(30, 35, 56, 0.75)) !important;
  box-shadow:
    inset 0 1px 0 0 rgba(126, 200, 227, 0.18),
    inset 1px 0 0 0 rgba(126, 200, 227, 0.10),
    inset 0 -1px 0 0 rgba(126, 200, 227, 0.04),
    inset -1px 0 0 0 rgba(126, 200, 227, 0.04),
